"use client";
import { useRef, type ReactNode } from "react";
import { useScrollMotion, type ScrollMotionProps } from "./scroll-shared";
import { scrollMixColor, scrollRange } from "./scroll-math";
export interface BackgroundColorStop {
  at: number;
  background: string;
  color?: string;
}
export interface BackgroundColorProps extends ScrollMotionProps {
  stops: readonly BackgroundColorStop[];
  children: ReactNode;
}
/** A local color surface; no global body styles are changed. */
export function BackgroundColor({ stops, children, ...props }: BackgroundColorProps) {
  const root = useRef<HTMLDivElement>(null),
    ordered = [...stops].sort((a, b) => a.at - b.at);
  useScrollMotion(
    root,
    props,
    ({ progress: p, reduced }) => {
      const first = ordered[0];
      if (!first) return;
      let a = first,
        b = first;
      for (const stop of ordered) {
        if (stop.at <= p) a = stop;
        if (stop.at >= p) {
          b = stop;
          break;
        }
        b = stop;
      }
      const q = reduced ? Number(p >= b.at) : scrollRange(p, a.at, b.at);
      root.current!.style.backgroundColor = scrollMixColor(a.background, b.background, q);
      root.current!.style.color = scrollMixColor(
        a.color ?? "#171717",
        b.color ?? a.color ?? "#171717",
        q,
      );
    },
    JSON.stringify(ordered),
    true,
  );
  return (
    <div
      ref={root}
      data-scroll-animation="background-color"
      className={props.className}
      style={{
        width: "100%",
        height: "100%",
        background: ordered[0]?.background,
        color: ordered[0]?.color,
        ...props.style,
      }}
    >
      {children}
    </div>
  );
}
